import json, random, subprocess, sys, itertools, ipaddress
sys.path.insert(0,'/workspace/tmp/t')
import ref

NAMES = ['w.t.','d.t.','d2.t.','e.t.','s.t.','n.t.','a.sub.t.','a.b.sub.t.','x.t.','*.t.','sub.t.','t.','y.']
TYPES = ['A','AAAA','TXT','CNAME']

def gen2(rng):
    recs = [
        {'owner':'w.t.','type':'CNAME','data':'e.t.'},
        {'owner':'d.t.','type':'CNAME','data':'d2.t.'},
        {'owner':'d2.t.','type':'CNAME','data':'e.t.'},
        {'owner':'e.t.','type':'A','data':'1.1.1.1'},
        {'owner':'e.t.','type':'AAAA','data':'2001:db8::1'},
        {'owner':'s.t.','type':'A','data':'2.2.2.2'},
        {'owner':'n.t.','type':'TXT','data':'x'},
        {'owner':'*.sub.t.','type':'A','data':'3.3.3.3'},
        {'owner':'*.t.','type':'CNAME','data':'e.t.'},
        {'owner':'t.','type':'TXT','data':'apex'},
        {'owner':'loop.t.','type':'CNAME','data':'loop.t.'},
        {'owner':'p.t.','type':'CNAME','data':'q.t.'},
        {'owner':'q.t.','type':'CNAME','data':'p.t.'},
        {'owner':'out.t.','type':'CNAME','data':'y.'},
    ]
    zones = [{'origin':'t.','records':recs}]
    if rng.random() < 0.4:
        zones.append({'origin':'.','records':[{'owner':'y.','type':'A','data':'9.9.9.9'}]})
    profiles=[]
    for i in range(rng.randint(1,8)):
        profiles.append({'id':'p%d'%i,'max_aliases':rng.choice([0,1,2,8]),
                         'cname':rng.choice(['follow','stop']),
                         'wildcard':rng.choice(['rfc','off','one-label'])})
    queries=[]
    for i in range(rng.randint(0,12)):
        queries.append({'id':'q%d'%i,'name':rng.choice(NAMES),'type':rng.choice(TYPES),'cost':rng.choice([1,2,3,5,8])})
    obs=[]
    for i in range(rng.randint(0,6)):
        if not queries or not profiles: break
        if rng.random()<0.3:
            res={'status':'timeout'}
        else:
            ans=[]
            for _ in range(rng.randint(0,4)):
                t=rng.choice(TYPES)
                d={'A':'1.1.1.1','AAAA':'2001:db8::1','TXT':'x','CNAME':'e.t.'}[t]
                ans.append({'owner':rng.choice(NAMES),'type':t,'data':d})
            res={'status':'response','rcode':rng.choice(['NOERROR','NXDOMAIN','SERVFAIL','REFUSED']),'answer':ans}
        obs.append({'id':'o%d'%i,'query':rng.choice(queries)['id'],'profile':rng.choice(profiles)['id'],'result':res})
    return {'zones':zones,'profiles':profiles,'queries':queries,'observations':obs}

def check(doc):
    zs = ref.build(doc['zones'])
    proj={}
    for q in doc['queries']:
        for p in doc['profiles']:
            rc,term,fin,ans,tr = ref.resolve(zs, q['name'].lower(), q['type'], p)
            proj[(q['id'],p['id'])]=(rc,frozenset(ans))
    eq,basis,cost,count = ref.basis_bruteforce(doc['profiles'], doc['queries'], proj)
    p=subprocess.run([sys.executable,'-I','/workspace/submission/main.py'],input=json.dumps(doc).encode(),capture_output=True,timeout=60)
    assert p.returncode==0, p.stderr[:300]
    out=json.loads(p.stdout.decode())
    if 'error' in out: return ('rejected', out)
    exp_runs=[]
    for q in sorted(doc['queries'], key=lambda x:x['id']):
        for pr in sorted(doc['profiles'], key=lambda x:x['id']):
            prof=[x for x in doc['profiles'] if x['id']==pr['id']][0]
            rc,term,fin,ans,tr = ref.resolve(zs, q['name'].lower(), q['type'], prof)
            exp_runs.append({'query':q['id'],'profile':pr['id'],'rcode':rc,'termination':term,'final_name':fin,
                             'answer':[{'owner':o,'type':t,'data':d} for o,t,d in ans],'trace':tr})
    if out['runs']!=exp_runs: return ('runs-mismatch',out['runs'],exp_runs)
    exp_audits=[]
    for o in sorted(doc['observations'], key=lambda x:x['id']):
        if o['result']['status']=='timeout':
            exp_audits.append({'id':o['id'],'verdict':'unobserved','different':[]})
        else:
            r=proj[(o['query'],o['profile'])]; orcr=o['result']['rcode']
            oset=frozenset((x['owner'].lower(),x['type'],
                            ipaddress.IPv6Address(x['data']).compressed if x['type']=='AAAA' else (x['data'].lower() if x['type']=='CNAME' else x['data']))
                           for x in o['result']['answer'])
            d=[]
            if r[0]!=orcr: d.append('rcode')
            if r[1]!=oset: d.append('answer')
            exp_audits.append({'id':o['id'],'verdict':'match' if not d else 'divergence','different':d})
    if out['audits']!=exp_audits: return ('audits-mismatch',out['audits'],exp_audits)
    dg=out['diagnostic']
    if dg['equivalence']!=eq: return ('eq-mismatch',dg['equivalence'],eq)
    if (dg['cost'],dg['count'])!=(cost,count): return ('cost-mismatch',dg,(cost,count,basis))
    if dg['basis']!=basis:
        if (sum(x['cost'] for x in doc['queries'] if x['id'] in dg['basis']),len(dg['basis']))!=(cost,count):
            return ('basis-suboptimal',dg,(cost,count,basis))
        for a,b in itertools.combinations(sorted(x['id'] for x in doc['profiles']),2):
            if any(proj[(q,a)]!=proj[(q,b)] for q in [x['id'] for x in doc['queries']]):
                if not any(proj[(q,a)]!=proj[(q,b)] for q in dg['basis']):
                    return ('basis-invalid',dg,(cost,count,basis))
    return ('ok',)

if __name__ == '__main__':
    import collections
    fails={}; sizes=collections.Counter()
    N=int(sys.argv[1]) if len(sys.argv)>1 else 500
    for i in range(N):
        rng=random.Random(i)
        doc=gen2(rng)
        try: res=check(doc)
        except Exception:
            import traceback; traceback.print_exc(); res=('exception',)
        if res[0]!='ok':
            fails.setdefault(res[0],[]).append(i)
            print('FAIL',i,res[0]); print(json.dumps(doc))
            if len(fails)>2: break
        else:
            try:
                out=json.loads(subprocess.run([sys.executable,'-I','/workspace/submission/main.py'],input=json.dumps(doc).encode(),capture_output=True).stdout.decode())
                sizes[len(out['diagnostic']['basis'])]+=1
            except Exception: pass
    print('done',{k:(len(v),v[:4]) for k,v in fails.items()})
    print('basis sizes',dict(sizes))
